import uuid
import json

try:
    item = _items[0]
    raw = item.get('json', {}) or {}

    body = raw.get('body', {}) or {}
    if isinstance(body, str):
        body = body.strip()
        try:
            body = json.loads(body) if body else {}
        except json.JSONDecodeError:
            body = {}
    if not isinstance(body, dict):
        body = {}

    document_id_filter = str(body.get('document_id') or '').strip().lower()
    if document_id_filter:
        try:
            uuid.UUID(document_id_filter)
        except ValueError:
            raise ValueError("Invalid format for 'document_id'. Must be a valid UUID.")
    else:
        document_id_filter = None

    return [{
        "json": {
            "document_id_filter": document_id_filter,
            "collection_name": raw.get('COLLECTION_NAME', 'ocr_documents_search')
        },
        "pairedItem": 0
    }]

except ValueError as e:
    print(f"Validation Error: {e}")
    raise

except IndexError:
    print("Error: The input to the Code node is empty.")
    raise ValueError("No input data received.")

