import json

cfg = _items[0]['json']
base_url = (cfg.get('QDRANT_BASE_URL') or '').rstrip('/')
collection = cfg.get('COLLECTION_NAME')
fields = json.loads(cfg.get('METADATA_TEXT_FIELDS') or '[]')

output = []
for field in fields:
    output.append({
        'json': {
            'field_name': field,
            'url': f"{base_url}/collections/{collection}/index",
            'body': {
                'field_name': field,
                'field_schema': {
                    'type': 'text',
                    'tokenizer': 'word',
                    'min_token_len': 2,
                    'lowercase': True
                }
            }
        }
    })
return output
